// src/core/visual.ts
var USE_LABEL = {
  cover: "\u5C01\u9762",
  article: "\u6B63\u6587\u914D\u56FE",
  info: "\u4FE1\u606F\u56FE",
  carousel: "\u5C0F\u7EA2\u4E66\u7EC4\u56FE",
  comic: "\u6F2B\u753B",
  slides: "\u5E7B\u706F\u7247",
  avatar: "\u5934\u50CF\u63D2\u753B",
  layout: "\u7248\u5F0F\u53C2\u8003"
};
function category(id) {
  const p = [
    ["cover", ["4-C", "6-C"]],
    ["article", ["4-I", "7-I"]],
    ["carousel", ["4-X"]],
    ["info", ["4-F"]],
    ["comic", ["4-M"]],
    ["avatar", ["6-A"]],
    ["slides", ["4-S"]]
  ];
  for (const [k, v] of p) if (v.some((x) => id.startsWith(x))) return k;
  return "layout";
}
var cache = null;
async function loadSamples(p) {
  if (cache) return cache;
  let raw = await p.readText(p.p("skills", "media-visual-hub", "references", "samples.json"));
  if (!raw) raw = samples_default;
  const out = [];
  try {
    const cat = JSON.parse(raw);
    for (const groups of Object.values(cat))
      for (const g of groups) for (const it of g.items || []) out.push({ id: it.id, name: it.name, url: it.url, original: it.original, use: category(it.id), group: g.title, source: g.source });
  } catch (e) {
  }
  cache = out;
  return out;
}
async function sampleById(p, id) {
  if (!id) return null;
  return (await loadSamples(p)).find((s) => s.id === id) || null;
}
function sampleLabel(s, id) {
  return s ? `${s.id} ${s.name}` : id ? id : "\u4E0D\u7528\u6837\u7247";
}
async function sampleImagePath(p, s) {
  const rel = (0, import_obsidian.normalizePath)(p.p("X", "\u6837\u7247", s.id + ".png"));
  const abs = path.join(p.vaultBase(), rel);
  if (await p.app.vault.adapter.exists(rel)) return abs;
  let buf = null;
  for (const u of [s.url, s.original]) {
    try {
      buf = (await (0, import_obsidian.requestUrl)({ url: u, throw: true })).arrayBuffer;
      if (buf && buf.byteLength > 1e3) break;
    } catch (e) {
    }
  }
  if (!buf) throw new Error("\u6837\u7247 " + s.id + " \u4E0B\u8F7D\u5931\u8D25");
  const bmp = await createImageBitmap(new Blob([buf]));
  const scale = Math.min(1, 1280 / Math.max(bmp.width, bmp.height));
  const c = document.createElement("canvas");
  c.width = Math.round(bmp.width * scale);
  c.height = Math.round(bmp.height * scale);
  c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
  const blob = await new Promise((res) => c.toBlob((b) => res(b), "image/png"));
  await p.ensureFolder(p.p("X", "\u6837\u7247"));
  await p.app.vault.adapter.writeBinary(rel, await blob.arrayBuffer());
  return abs;
}
function styledBrief(s, o) {
  return [
    "\u8BF7\u76F4\u63A5\u7528\u4F60\u7684\u56FE\u7247\u751F\u6210\u5DE5\u5177\u753B\u4E00\u5F20\u56FE\uFF0C\u4E0D\u8981\u5199\u4EE3\u7801\uFF0C\u4E0D\u8981\u7528\u547D\u4EE4\u884C\uFF0C\u753B\u5B8C\u53EA\u56DE\u590D\u4E00\u53E5\u8BDD\u3002",
    `\u53C2\u8003\uFF1A${s.id} \xB7 ${s.name}\uFF08\u9644\u56FE\u5C31\u662F\u8FD9\u5F20\u6837\u7247\uFF0C\u6765\u6E90\uFF1A${s.source}\uFF09`,
    `\u7528\u9014\uFF1A${USE_LABEL[s.use] || s.use}`,
    `\u53D1\u5E03\u4F4D\u7F6E\uFF1A${o.platform}`,
    `\u6BD4\u4F8B\uFF1A${o.ratio}`,
    `\u56FE\u4E0A\u6587\u5B57\uFF1A${o.text || "\u5C3D\u91CF\u4E0D\u653E\u5B57\uFF1B\u5982\u679C\u8981\u653E\uFF0C\u53EA\u653E 2 \u5230 6 \u4E2A\u4E2D\u6587\u5927\u5B57"}`,
    "\u5185\u5BB9\uFF1A",
    o.content.slice(0, 2500),
    o.extra ? "\u989D\u5916\u8981\u6C42\uFF1A" + o.extra : "",
    "",
    "\u5148\u770B\u9644\u56FE\u6837\u7247\uFF0C\u63D0\u53D6\u914D\u8272\u3001\u6784\u56FE\u3001\u8D28\u611F\u3001\u7559\u767D\u548C\u5B57\u4F53\u5C42\u7EA7\uFF0C\u518D\u7528\u4E8E\u672C\u6B21\u5185\u5BB9\uFF0C\u91CD\u65B0\u8BBE\u8BA1\u753B\u9762\u3002",
    "\u4E0D\u8981\u6CBF\u7528\u53C2\u8003\u56FE\u7684\u65E0\u5173\u6587\u6848\u3001\u5546\u6807\u3001\u6C34\u5370\u6216\u6570\u636E\uFF1B\u89E3\u91CA\u56FE\u8981\u4FDD\u6301\u903B\u8F91\u51C6\u786E\u3002\u4E0D\u8981\u771F\u5B9E\u540D\u4EBA\u7684\u8138\uFF0C\u4E0D\u8981\u54C1\u724C\u6807\u5FD7\u3002"
  ].filter(Boolean).join("\n");
}

// src/ui/stylepicker.ts
var import_obsidian2 = require("obsidian");
var ORDER = ["cover", "article", "info", "carousel", "comic", "slides", "avatar", "layout"];
var lastUse = "article";
var StylePicker = class extends import_obsidian2.Modal {
  constructor(p, current2, onPick, prefer) {
    super(p.app);
    this.p = p;
    this.current = current2;
    this.onPick = onPick;
    this.prefer = prefer;
    this.q = "";
  }
  async onOpen() {
    this.modalEl.addClass("gzh-stylepicker");
    this.titleEl.setText("\u9009\u914D\u56FE\u6837\u7247");
    const all = await loadSamples(this.p);
    const cur = all.find((s) => s.id === this.current);
    let use = cur ? cur.use : this.prefer || lastUse;
    const el = this.contentEl;
    const draw = () => {
      el.empty();
      el.createDiv({ cls: "gzh-muted", text: "\u6765\u81EA\u4F60\u7684\u6837\u7247\u5E93 media-visual-hub\u3002\u70B9\u4E00\u5F20\u5C31\u7528\u5B83\u7684\u98CE\u683C\uFF1A\u753B\u56FE\u65F6\u628A\u8FD9\u5F20\u6837\u7247\u4EA4\u7ED9 GPT\uFF0C\u53C2\u8003\u914D\u8272\u3001\u6784\u56FE\u3001\u8D28\u611F\u548C\u7559\u767D\uFF0C\u91CD\u65B0\u8BBE\u8BA1\u8FD9\u6B21\u7684\u5185\u5BB9\u3002" + (cur ? `  \u73B0\u5728\u7528\u7684\u662F\uFF1A${cur.id} ${cur.name}` : "") });
      const bar = el.createDiv({ cls: "gzh-bar wrap" });
      for (const u of ORDER) {
        const n = all.filter((s) => s.use === u).length;
        if (!n) continue;
        const b = bar.createEl("button", { text: `${USE_LABEL[u]} ${n}`, cls: "gzh-pill" + (use === u ? " is-on" : "") });
        b.onclick = () => {
          use = u;
          lastUse = u;
          draw();
        };
      }
      const none = bar.createEl("button", { text: "\u4E0D\u7528\u6837\u7247", cls: "gzh-pill" + (!this.current ? " is-on" : "") });
      none.onclick = () => {
        this.onPick("");
        this.close();
      };
      const q = bar.createEl("input", { type: "search", placeholder: "\u641C\u7F16\u53F7\u6216\u540D\u5B57\uFF0C\u6BD4\u5982 \u624B\u7ED8", value: this.q });
      q.oninput = () => {
        this.q = q.value;
        grid();
      };
      const box = el.createDiv({ cls: "gzh-style-grid" });
      const grid = () => {
        box.empty();
        const kw = this.q.trim().toLowerCase();
        const L = all.filter((s) => kw ? (s.id + s.name + s.group).toLowerCase().includes(kw) : s.use === use);
        for (const s of L) {
          const c = box.createDiv({ cls: "gzh-style-card" + (s.id === this.current ? " is-on" : "") });
          c.createEl("img", { attr: { src: s.url, loading: "lazy", alt: s.name } });
          c.createDiv({ cls: "gzh-style-name", text: `${s.id} ${s.name}` });
          c.onclick = () => {
            this.onPick(s.id);
            this.close();
          };
        }
        if (!L.length) box.createDiv({ cls: "gzh-empty", text: "\u6CA1\u6709\u7B26\u5408\u7684\u6837\u7247" });
      };
      grid();
    };
    draw();
  }
  onClose() {
    this.contentEl.empty();
  }
};

