  const subs = el.createDiv({ cls: "gzh-xsubs" });
  subs.style.display = "none"; // 导航已合并到上面一行
  if (st.sub === "process") st.sub = "today";
  for (const [k, label] of [
    ["today", "今日"],
    ["radar", "\u8BC4\u8BBA\u96F7\u8FBE"],
    ["process", "\u4E00\u952E\u52A0\u5DE5"],
    ["review", "\u590D\u76D8"]
  ]) {
    const b = subs.createEl("button", { text: label, cls: "gzh-xsub" + (st.sub === k ? " is-on" : "") });
    b.setAttribute("aria-pressed", String(st.sub === k));
    b.onclick = () => {
      st.sub = k;
      view.render();
    };
  }
  if (st.sub === "today") await renderToday(view, p, el, st);
  else if (st.sub === "process") processPanel(p, el, st, () => view.render());
