function xGrowthLine(p, el, rerender) {
  const s = p.settings;
  const log = s.xFollowers || {};
  const dates = Object.keys(log).sort();
  const goal = s.xGoal || 1e4;
  const goalDate = s.xGoalDate || "2026-11-13";
  const row = el.createDiv({ cls: "gzh-xgrowth" });
  const today = p.today();
  if (!dates.length) {
    row.createSpan({ text: `涨粉目标 ${goal.toLocaleString()}（${goalDate} 前）· 还没记录粉丝数` });
  } else {
    const last = dates[dates.length - 1], cur = log[last];
    const prev = dates.length > 1 ? log[dates[dates.length - 2]] : null;
    const daysLeft = Math.max(1, Math.ceil((Date.parse(goalDate + "T12:00:00") - Date.parse(today + "T12:00:00")) / 864e5));
    const need = Math.max(0, goal - cur);
    const perDay = Math.ceil(need / daysLeft);
    row.createSpan({ text: `粉丝 ${cur.toLocaleString()} / ${goal.toLocaleString()}` });
    row.createSpan({ cls: "gzh-muted", text: ` · 还差 ${need.toLocaleString()} · 剩 ${daysLeft} 天，需日均 +${perDay}` + (prev !== null ? ` · 上次记录以来 ${cur - prev >= 0 ? "+" : ""}${cur - prev}` : "") });
  }
  const b = row.createEl("button", { text: log[today] ? "改今天的粉丝数" : "记今天的粉丝数", cls: "gzh-mini" });
  b.onclick = () => {
    const Modal = require("obsidian").Modal;
    const m = new Modal(p.app);
    m.titleEl.setText("今天的粉丝数");
    const inp = m.contentEl.createEl("input", { type: "number", value: String(log[today] || (dates.length ? log[dates[dates.length - 1]] : "")) });
    inp.style.width = "100%";
    const save = m.contentEl.createEl("button", { text: "保存", cls: "mod-cta" });
    save.style.marginTop = "10px";
    const go = async () => { const v = parseInt(inp.value, 10); if (!(v >= 0)) return; s.xFollowers = { ...log, [today]: v }; await p.saveSettings(); m.close(); rerender(); };
    save.onclick = go;
    inp.onkeydown = (e) => { if (e.key === "Enter") go(); };
    m.open();
    setTimeout(() => inp.focus(), 30);
  };
}
