  g.fillStyle = "#71717a"; g.font = `bold 26px ${F}`; g.fillText(tool || "ChatGPT", P, P + 20);
  let y = P + 50;
  const qw = Math.min(W - 2 * P - 180, Math.max(...q.map((l) => { g.font = `30px ${F}`; return g.measureText(l).width; })) + 56);
  g.fillStyle = "#e4e4e7"; g.beginPath(); g.roundRect ? g.roundRect(W - P - qw, y, qw, qh, 28) : g.rect(W - P - qw, y, qw, qh); g.fill();
  g.fillStyle = "#18181b"; g.font = `30px ${F}`;
  q.forEach((l, i) => g.fillText(l, W - P - qw + 28, y + 52 + i * 44));
  y += qh + 36;
  g.fillStyle = "#ffffff"; g.beginPath(); g.roundRect ? g.roundRect(P, y, W - 2 * P, ah, 28) : g.rect(P, y, W - 2 * P, ah); g.fill();
  g.fillStyle = "#18181b"; g.font = `32px ${F}`;
