      const remove=actions.createEl("button",{text:"移除",cls:"gzh-mini"});remove.onclick=e=>{e.stopPropagation();p.x.mutateDay(it.postDate,d=>{const t=d.items.find(v=>v.id===it.id);if(t&&t.status!=="posted"){t.removedFromStatus=t.status;t.status="skipped";}});};
