var WHATSNEW_VERSION = "2026-10-11-all2";
async function demoNote(p) {
  const day = await p.loadTopics(p.today());
  if (day && day.pickedNote) {
    const f = p.app.vault.getAbstractFileByPath(day.pickedNote);
    if (f instanceof import_obsidian10.TFile) return f;
  }
  const dir = p.app.vault.getAbstractFileByPath(p.p("\u7A3F\u4EF6"));
  if (dir instanceof import_obsidian10.TFolder) {
    const files = dir.children.filter((c) => c instanceof import_obsidian10.TFile && c.extension === "md").sort((a, b) => b.stat.mtime - a.stat.mtime);
    if (files[0]) return files[0];
  }
  return null;
}
async function openDemoNote(p) {
  const f = await demoNote(p);
  document.querySelectorAll(".gzh-tour-note").forEach((e) => e.removeClass("gzh-tour-note"));
  if (!f) return null;
  const mds = p.app.workspace.getLeavesOfType("markdown");
  let leaf = mds.find((l) => l.getViewState().state?.file === f.path) || null;
  if (!leaf && mds[0]) {
    leaf = mds[0];
    await leaf.openFile(f);
  }
  if (!leaf) {
    leaf = p.app.workspace.getLeaf("split", "vertical");
    await leaf.openFile(f);
  }
  await p.app.workspace.revealLeaf(leaf);
  if (leaf.loadIfDeferred) await leaf.loadIfDeferred();
  const mv = leaf.view;
  leaf.containerEl?.addClass("gzh-tour-note");
  return mv;
}
function selectDemo(mv) {
  const ed = mv.editor;
  const lines = ed.getValue().split("\n");
  let start = lines.findIndex((l) => l.includes("%% \u6B63\u6587\u5F00\u59CB %%"));
  if (start < 0) start = 0;
  for (let i = start + 1; i < lines.length; i++) {
    const l = lines[i].trim();
    if (l.length >= 20 && !/^(#|%%|!\[|>|-|\*|【)/.test(l)) {
      const from = { line: i, ch: 0 }, to = { line: i, ch: lines[i].length };
      ed.setSelection(from, to);
      ed.scrollIntoView({ from, to }, true);
      return { from: ed.posToOffset(from), to: ed.posToOffset(to) };
    }
  }
  return null;
}
function removeDemoFloat() {
  document.querySelectorAll(".gzh-float-demo").forEach((e) => e.remove());
}
