var DiffModal = class extends import_obsidian12.Modal {
  constructor(app, a, b, label) {
    super(app);
    this.a = a;
    this.b = b;
    this.label = label;
  }
  onOpen() {
    this.modalEl.addClass("gzh-cvdiff");
    this.titleEl.setText("\u5BF9\u6BD4\uFF1A" + this.label + " \u2192 \u73B0\u5728");
    const pa = this.a.split(/\n+/).filter((x) => x.trim());
    const pb = this.b.split(/\n+/).filter((x) => x.trim());
    const sa = new Set(pa), sb = new Set(pb);
    const box = this.contentEl.createDiv({ cls: "gzh-cvdiff-box" });
    let i = 0, j = 0;
    let same = 0;
    while (i < pa.length || j < pb.length) {
      if (i < pa.length && j < pb.length && pa[i] === pb[j]) {
        same++;
        i++;
        j++;
        continue;
      }
      if (same) {
        box.createDiv({ cls: "gzh-muted", text: `\uFF08${same} \u6BB5\u76F8\u540C\uFF09` });
        same = 0;
      }
      if (i < pa.length && !sb.has(pa[i])) box.createDiv({ cls: "gzh-cvdel", text: pa[i++] });
      else if (j < pb.length && !sa.has(pb[j])) box.createDiv({ cls: "gzh-cvadd", text: pb[j++] });
      else {
        if (i < pa.length) i++;
        if (j < pb.length) j++;
      }
    }
    if (same) box.createDiv({ cls: "gzh-muted", text: `\uFF08${same} \u6BB5\u76F8\u540C\uFF09` });
  }
};

