var editorial_examples_default = "# \u5DF2\u9A8C\u8BC1\u6210\u7A3F\u7684\u7F16\u8F91\u5B9E\u4F8B\n\n\u6848\u4F8B\uFF1A\u300A\u5B59\u5B87\u6668\xD7\u90B5\u827E\u4F26\u7206\u706B\u5BF9\u8C08\uFF1A\u5E74\u8F7B\u4EBA\u5982\u4F55\u6293\u4F4F AI \u65F6\u4EE3\u7684\u673A\u4F1A\uFF1F\uFF08\u539F\u7A3F\u7CBE\u534E\u6574\u7406\u7248\uFF09\u300B\uFF0C\u7528\u6237\u4E8E2026-10-11\u786E\u8BA4\u4E3A\u6700\u7EC8\u6210\u7A3F\u3002\n\n\u5B9E\u4F8B\u7528\u4E8E\u590D\u7528\u51B3\u7B56\uFF0C\u4E0D\u7528\u4E8E\u590D\u8FF0\u4EBA\u7269\u7684\u4E8B\u5B9E\u4E3B\u5F20\u3002\u884C\u53F7\u6765\u81EA\u7528\u6237\u63D0\u4F9B\u7684541\u884C transcript.txt\uFF0C\u4EC5\u9002\u7528\u4E8E\u8BE5\u7248\u672C\u3002\n\n## \u4E03\u79CD\u8F6C\u6362\n\n### \u4FDD\u7559\u4EBA\u7269\u8BED\u8A00\uFF0C\u518D\u89E3\u91CA\n\n\u539F\u7A3FL25\u3001L29\u3001L31\u5206\u522B\u8C08\u5B59\u5B66\u3001\u8EAB\u4F53\u5347\u7EA7\u548C\u5FC3\u6001\u5347\u7EA7\u3002\u6210\u7A3F\u5728\u5F00\u5934\u5EFA\u7ACB\u4E09\u9879\u6846\u67B6\uFF0C\u6CA1\u6709\u6CDB\u5316\u6210\u201C\u8BA4\u77E5\u3001\u5065\u5EB7\u3001\u81EA\u4FE1\u201D\u3002\n\n\u4FDD\u7559\u9AD8\u8FA8\u8BC6\u5EA6\u547D\u540D\uFF0C\u7D27\u63A5\u7740\u8BF4\u660E\u89E3\u51B3\u4EC0\u4E48\u95EE\u9898\u3002\u4F46\u6210\u7A3F\u628A\u4E09\u5904\u610F\u601D\u538B\u6210\u4E00\u6BB5\u5F15\u8BED\uFF1B\u4E0B\u4E00\u6B21\u5B9C\u5199\u201C\u53EF\u4EE5\u628A\u4ED6\u7684\u610F\u601D\u6574\u7406\u4E3A\u2026\u2026\u201D\uFF0C\u4E0D\u4F5C\u4E3A\u540C\u4E00\u5904\u9010\u5B57\u5F15\u7528\u3002\n\n### \u6807\u9898\u7528\u6709\u4F9D\u636E\u7684\u53CD\u5DEE\n\n\u4E2D\u95F4\u521D\u7A3F\uFF1A\u201C\u7EF4\u62A4\u8EAB\u4F53\uFF0C\u662F\u4E3A\u4E86\u8BA9\u957F\u671F\u8BA1\u5212\u6709\u6267\u884C\u8005\u201D\u3002\u6700\u7EC8\u6210\u7A3F\uFF1A\u201CAI\u8D8A\u5F3A\uFF0C\u4EBA\u7684\u8EAB\u4F53\u53CD\u800C\u8D8A\u503C\u94B1\u201D\u3002\u539F\u7A3FL53\u8C08\u5E74\u8F7B\u4E0E\u5BFF\u547D\uFF0CL123\u2014125\u8C08\u78B3\u57FA\u8EAB\u4F53\u4E0E\u7845\u57FAAI\u3002\n\n\u6807\u9898\u5C06\u719F\u6089\u8D8B\u52BF\u4E0E\u88AB\u5FFD\u7565\u7684\u53D8\u91CF\u76F8\u8FDE\uFF0C\u6B63\u6587\u5FC5\u987B\u652F\u6491\u8FD9\u79CD\u8FDE\u63A5\u3002\u5176\u4ED6\u6750\u6599\u6CA1\u6709\u8FD9\u7EC4\u89C2\u70B9\u65F6\u4E0D\u5957\u7528\u3002\n\n### \u7528\u5C11\u91CF\u5F3A\u4F8B\u5B50\u627F\u8F7D\u89C2\u70B9\n\n\u539F\u7A3FL83\u201495\u901A\u8FC7\u770B\u623F\u3001\u4E70\u8F66\u3001\u804C\u4E1A\u4E0E\u6E38\u620F\u8BB2\u63A2\u56FE\uFF0C\u8FD8\u6709\u590D\u6742\u7684\u6982\u7387\u8BF4\u6CD5\u3002\u6210\u7A3F\u7559100\u5957\u623F\u548C\u63A2\u56FE\uFF0C\u63A5\u5230\u4E13\u4E1A\u4E0E\u521B\u4E1A\uFF0C\u5220\u590D\u6742\u6982\u7387\u63A8\u5BFC\u3002\n\n\u7559\u8DB3\u591F\u5177\u4F53\u7684\u4F8B\u5B50\uFF0C\u5220\u91CD\u590D\u53CA\u9AD8\u9A8C\u8BC1\u6210\u672C\u7684\u679D\u8282\u3002\n\n### \u63D0\u70BC\u5171\u540C\u673A\u5236\n\n\u539F\u7A3FL73\u201479\u3001L99\u2014103\u6D89\u53CA\u4F9B\u9700\u3001\u5168\u7403\u5E02\u573A\u3001\u6570\u636E\u4E0E\u884C\u4E1A\u3002\u6210\u7A3F\u7528\u201C\u4EF7\u503C\u65AD\u70B9\u201D\u7EC4\u7EC7\u4F9B\u9700\u672A\u8FDE\u63A5\u3001\u6570\u636E\u672A\u5904\u7406\u3001\u77E5\u8BC6\u672A\u8F6C\u6210\u4EA7\u54C1\u7B49\u3002\n\n\u65B0\u6982\u62EC\u8BCD\u987B\u6709\u591A\u4E2A\u4F8B\u5B50\u652F\u6491\uFF0C\u653E\u5728\u4F5C\u8005\u53D9\u8FF0\u4E2D\u3002\u201C\u4EF7\u503C\u65AD\u70B9\u201D\u4E0D\u81EA\u52A8\u6210\u4E3A\u53D7\u8BBF\u8005\u539F\u8BDD\uFF0C\u201C\u964D\u4F4E\u5341\u500D\u201D\u4E5F\u4E0D\u80FD\u4ECE\u4E00\u822C\u964D\u672C\u8BF4\u6CD5\u63A8\u5BFC\u3002\n\n### \u4E3A\u5173\u952E\u6280\u672F\u505A\u6700\u5C0F\u7FFB\u8BD1\n\n\u539F\u7A3FL49\u8C08API\u3001\u672C\u5730\u6587\u4EF6\u4E0E\u6A21\u578B\uFF1BL193\u2014195\u3001L223\u2014227\u8C08\u673A\u5668\u8D27\u5E01\u4E0E\u652F\u4ED8\u3002\u4E2D\u95F4\u7A3F\u6DE1\u5316API\uFF0C\u628ACrypto\u5E76\u5165\u7ECF\u9A8C\u6570\u5B57\u5316\uFF0C\u6210\u7A3F\u6062\u590DAPI\u89E3\u91CA\u4E0ECrypto\u72EC\u7ACB\u8282\u3002\n\n\u5173\u952E\u5185\u5BB9\u96BE\u61C2\u65F6\uFF0C\u628A\u5B83\u7FFB\u8BD1\u6210\u666E\u901A\u95EE\u9898\uFF0C\u4E0D\u9ED8\u8BA4\u5220\u6389\uFF0C\u4E5F\u4E0D\u6269\u6210\u767E\u79D1\u3002\n\n### \u89E3\u91CA\u5206\u6563\u89C2\u70B9\u7684\u5F20\u529B\n\n\u539F\u7A3FL29\u8C08\u72EC\u7ACB\u6267\u884C\uFF0CL271\u2014277\u8C08Small Ego\u3002\u6210\u7A3F\u540C\u8282\u89E3\u91CA\u575A\u6301\u884C\u52A8\u4E0E\u63A5\u53D7\u66F4\u65B0\u7684\u5173\u7CFB\u3002\n\n\u8FD9\u662F\u7F16\u8F91\u7EFC\u5408\uFF0C\u4E0D\u80FD\u8BF4\u53D7\u8BBF\u8005\u9010\u5B57\u7ED9\u51FA\u4E86\u8FD9\u6761\u5B8C\u6574\u89C4\u5219\u3002\n\n### \u53BB\u566A\u4F46\u4E0D\u53BB\u950B\u8292\n\n\u539F\u7A3FL31\u201433\u8C08\u767E\u5206\u767E\u76F8\u4FE1AI\uFF0C\u6210\u7A3F\u7ED3\u5408\u591A\u6A21\u578B\u3001\u8FA9\u8BBA\u4E0E\u8C03\u4F18\uFF0C\u7ED9\u51FA\u73B0\u5B9E\u9A8C\u6536\u7684\u4F5C\u8005\u89E3\u91CA\u3002\n\n\u539F\u7A3FL129\u2014143\u6709\u5F3A\u5065\u5EB7\u65AD\u8A00\uFF0C\u6210\u7A3F\u7559\u8EAB\u4F53\u8D2B\u5BCC\u3001\u8D26\u6237\u548C\u670D\u52A1\u5668\u6BD4\u55BB\uFF0C\u5220\u5BFF\u547D\u6BD4\u4F8B\u5E76\u63D0\u793A\u6BD4\u55BB\u8FB9\u754C\u3002\n\n\u539F\u7A3F\u7ED3\u5C3E\u4E92\u6367\u3001\u62DC\u5E74\u5F0F\u8F6C\u53D1\u8BC9\u6C42\uFF0C\u6210\u7A3F\u8F6C\u6210\u52AA\u529B\u5374\u8FF7\u832B\u7684\u5E74\u8F7B\u4EBA\u3002\n\n\u51CF\u5C11\u963B\u788D\u7406\u89E3\u7684\u566A\u97F3\uFF0C\u4FDD\u7559\u5F20\u529B\u3002\u8FB9\u754C\u77ED\u800C\u5C31\u8FD1\uFF0C\u4E0D\u53E6\u5199\u901A\u7528\u514D\u8D23\u58F0\u660E\u3002\n\n## \u4E0D\u4ECE\u5355\u7BC7\u6837\u672C\u56FA\u5316\u7684\u89C4\u5219\n\n- 11\u8282\u300113\u5F20\u56FE\u300123\u6BB5\u5F15\u7528\u662F\u6837\u672C\u7279\u5F81\uFF0C\u4E0D\u662F\u914D\u989D\u3002\n- \u53CD\u5E38\u8BC6\u662F\u9009\u6750\u6807\u51C6\uFF0C\u4E0D\u662F\u6BCF\u53E5\u8BDD\u5FC5\u987B\u53CD\u8F6C\u3002\n- \u540D\u4EBA\u3001Crypto\u3001\u5168\u7403\u5E02\u573A\u3001\u5065\u5EB7\u53EA\u5728\u6750\u6599\u9700\u8981\u65F6\u51FA\u73B0\u3002\n- \u70ED\u5EA6\u3001\u65F6\u957F\u3001\u5C65\u5386\u4E0D\u80FD\u590D\u5236\u5230\u65B0\u91C7\u8BBF\u3002\n- \u4E0D\u8FFD\u52A090\u5929\u8BA1\u5212\u662F\u672C\u7BC7\u7CBE\u534E\u7248\u7684\u9009\u62E9\uFF0C\u4E0D\u9650\u5236\u7528\u6237\u8981\u6C42\u6267\u884C\u65B9\u6848\u3002\n\n## \u884C\u4E3A\u81EA\u68C0\u7247\u6BB5\n\n\u6750\u6599\u5148\u8C08\u8BAD\u7EC3\u8BB0\u5F55\uFF0C\u4E2D\u95F4\u63A8\u8350\u81EA\u5BB6\u5DE5\u5177\uFF0C\u540E\u9762\u8C08\u7ECF\u9A8C\u6210\u4E3AAI\u8BED\u6599\uFF1A\u5E94\u4FDD\u7559\u8BB0\u5F55\u6848\u4F8B\u3001\u5220\u9664\u5BFC\u6D41\uFF0C\u4F9D\u4E3B\u95EE\u9898\u7EC4\u7EC7\u4E2A\u4EBA\u6570\u636E\u548C\u77E5\u8BC6\u6570\u5B57\u5316\uFF0C\u4E0D\u80FD\u7167\u5F55\u97F3\u987A\u5E8F\u3002\n\n\u6750\u6599\u4E00\u5904\u8BF4\u5B8C\u5168\u76F8\u4FE1AI\uFF0C\u53E6\u4E00\u5904\u8C08\u8FA9\u8BBA\u3001\u591A\u6A21\u578B\uFF1A\u5E94\u5448\u73B0\u4E24\u5C42\u610F\u601D\uFF0C\u8BF4\u660E\u4F5C\u8005\u7EFC\u5408\u5224\u65AD\uFF0C\u4E0D\u6311\u4E00\u53E5\u628A\u4EBA\u7269\u5851\u9020\u6210\u76F8\u53CD\u6001\u5EA6\u3002\n";

