var source_input_workflow_default = "# YouTube\u4E0E\u5C0F\u5B87\u5B99\u8F93\u5165\n\n1. \u8BC6\u522B\u5355\u96C6\uFF0C\u6838\u5B9E\u6807\u9898\u3001\u4EBA\u7269\u4E0E\u6765\u6E90\u3002\u94FE\u63A5\u5E26\u8D77\u59CB\u65F6\u95F4\u4E0D\u81EA\u52A8\u8868\u793A\u53EA\u6574\u7406\u8BE5\u65F6\u95F4\u4E4B\u540E\uFF0C\u9664\u975E\u7528\u6237\u6307\u5B9A\u8303\u56F4\u3002\n2. \u4F18\u5148\u7528\u6237\u672C\u5730\u539F\u7A3F\uFF0C\u5176\u6B21\u5E73\u53F0\u5B57\u5E55/\u6587\u5B57\u7A3F\uFF0C\u518D\u6B21\u53EF\u6838\u9A8C\u516C\u5F00\u9010\u5B57\u7A3F\u3002\u8BB0\u5F55\u6765\u6E90\u3001\u8BED\u8A00\u3001\u65F6\u95F4\u6233\u4E0E\u8986\u76D6\u8303\u56F4\u3002\u4F7F\u7528\u53EF\u7528\u8FDE\u63A5\u5668\u3001\u6D4F\u89C8\u6216\u8F6C\u5199\u80FD\u529B\uFF0C\u4E0D\u80FD\u5047\u8BBE\u5E73\u53F0\u5FC5\u6709\u5B57\u5E55\u6216\u53EF\u4E0B\u8F7D\u97F3\u9891\u3002\n3. YouTube\u4F18\u5148\u771F\u5B9E\u5B57\u5E55\uFF1B\u5C0F\u5B87\u5B99\u68C0\u67E5\u5355\u96C6\u9875\u3001\u5B8C\u6574\u6587\u5B57\u7A3F\u53CA\u53EF\u8BBF\u95EE\u97F3\u9891\u3002\u6709\u5408\u6CD5\u53EF\u8BBF\u95EE\u97F3\u89C6\u9891\u4E14\u6709\u8F6C\u5199\u5DE5\u5177\u65F6\u518D\u8F6C\u5199\uFF0C\u957F\u6750\u6599\u5206\u6BB5\u540E\u6838\u5BF9\u8854\u63A5\u3002\u8BBF\u95EE\u53D7\u9650\u3001\u7F3A\u5C11\u97F3\u9891\u6216\u65E0\u5DE5\u5177\u65F6\u8BF4\u660E\u5177\u4F53\u7F3A\u53E3\uFF0C\u8BF7\u7528\u6237\u63D0\u4F9B\u6587\u5B57\u7A3F\u6216\u53EF\u8BBF\u95EE\u97F3\u89C6\u9891\uFF0C\u4E0D\u627F\u8BFA\u4EFB\u610F\u94FE\u63A5\u90FD\u80FD\u8F6C\u5199\u3002\n4. \u53EA\u6709\u7B80\u4ECB\u6216\u4E0D\u5B8C\u6574\u5B57\u5E55\u65F6\u660E\u786E\u8986\u76D6\u8303\u56F4\uFF0C\u4E0D\u751F\u6210\u8C8C\u4F3C\u5B8C\u6574\u7684\u957F\u6587\u548C\u7F3A\u5931\u5185\u5BB9\u7684\u914D\u56FE\u3002\u4E0D\u7528\u672A\u8BFB\u7684\u7B2C\u4E09\u65B9\u6458\u8981\u66FF\u4EE3\u539F\u7A3F\u3002\u5C0A\u91CD\u6765\u6E90\u4F7F\u7528\u9650\u5236\uFF0C\u7528\u6237\u539F\u7A3F\u4E0E\u5916\u90E8\u7F51\u9875\u5206\u522B\u5904\u7406\u3002\n\n\u901A\u8BFB\u539F\u7A3F\u540E\u6309\u4E3BSkill\u6574\u7406\u4E2D\u6587\u6587\u7AE0\uFF0C\u82F1\u6587\u5F15\u6587\u6807\u4E3A\u8BD1\u6587\uFF1B\u4FDD\u7559\u6765\u6E90\u94FE\u63A5\u548C\u5DE5\u4F5C\u7A3F\u5B9A\u4F4D\uFF0C\u804C\u4F4D\u3001\u4EA7\u54C1\u8BA1\u5212\u4E0E\u89C2\u70B9\u6309\u5F55\u5236\u65F6\u70B9\u5F52\u56E0\u3002\u9ED8\u8BA4\u4EA4\u4ED8\u6587\u7AE0\u4E0E\u7B2C\u4E00\u6B63\u6587\u7AE0\u8282\u5B8C\u6574\u5185\u5BB9\u914D\u56FE\uFF083:2\uFF0C\u6781\u7B80\u89C6\u89C9\u9690\u55BB\u98CE\uFF09\uFF0C\u7B49\u7528\u6237\u786E\u8BA4\u540E\u5B8C\u6210\u5176\u4F59\u5404\u7AE0\u8282\u3002\n\nObsidian\u4FDD\u5B58\u9075\u5FAA [obsidian-export.md](obsidian-export.md)\uFF0C\u516C\u5F00Skill\u4E0E\u672C\u673A\u79C1\u4EBA\u914D\u7F6E\u5206\u79BB\uFF0C\u4E0D\u6CBF\u7528\u4E0A\u4E00\u7BC7\u6587\u4EF6\u540D\u6216\u65E5\u671F\u3002\n";

