var punk_illustration_workflow_default = "# \u6210\u7A3F\u7AE0\u8282Punk\u914D\u56FE\u5DE5\u4F5C\u6D41\n\n## \u9ED8\u8BA4\u6D41\u7A0B\u4E0E\u8986\u76D6\n\n\u4F7F\u7528\u5F53\u524D\u4EA4\u4ED8\u6587\u7AE0\u7684\u5B8C\u6574\u7AE0\u8282\u6B63\u6587\u3002\u9ED8\u8BA4\u7B2C\u4E00\u6B63\u6587\u7AE0\u8282\u5148\u751F\u6210\u4E00\u5F20\uFF0C3:2\uFF0C\u6781\u7B80\u89C6\u89C9\u9690\u55BB\u98CE\uFF1B\u8FD9\u4E9B\u662F\u5DF2\u786E\u8BA4\u504F\u597D\uFF0C\u4E0D\u91CD\u590D\u8BE2\u95EE\u3002\u7528\u6237\u786E\u8BA4\u9996\u56FE\u540E\uFF0C\u4E3A\u5176\u4F59\u6B63\u6587\u7AE0\u8282\u5206\u522B\u751F\u6210\u4E00\u5F20\u3002\u5C01\u9762\u53E6\u9009\u3002\n\n\u4FDD\u7559\u591A\u9009\u8303\u56F4\uFF1A\u5C01\u9762\u3001\u5168\u90E8\u6B63\u6587\u7AE0\u8282\u3001\u5177\u4F53\u7AE0\u8282\u7F16\u53F7\uFF1B\u4FDD\u7559\u751F\u6210\u65B9\u5F0F\uFF1A\u9996\u56FE\u8BD5\u770B\u3001\u5168\u90E8\u751F\u6210\u3001\u4EC5\u65B9\u6848/\u63D0\u793A\u8BCD\u3001\u4E0D\u914D\u56FE\u3002\u5F53\u6B21\u8981\u6C42\u4F18\u5148\uFF0C\u4E0D\u628A\u9ED8\u8BA4\u9009\u9879\u6216\u7B49\u5F85\u65F6\u95F4\u5F53\u6210\u786E\u8BA4\u3002\u65B0\u98CE\u683C\u6216\u5C3A\u5BF8\u7F3A\u5931\u65F6\u4F9Dpunk-cover\u8981\u6C42\u8BE2\u95EE\uFF1B\u9ED8\u8BA4\u53C2\u6570\u5B8C\u6574\u65F6\u76F4\u63A5\u6267\u884C\u3002\n\n## \u4ECE\u5B8C\u6574\u5185\u5BB9\u7F16\u8BD1\u753B\u9762\n\n\u52A0\u8F7Dpunk-cover\u7684SKILL.md\u3001\u98CE\u683C\u76EE\u5F55\u3001\u63D0\u793A\u8BCD\u84DD\u56FE\u53CA\u9009\u5B9A\u98CE\u683CMETA.md/STYLE.md\u3002\u6CBF\u7528\u98CE\u683C\u7684\u8272\u5F69\u3001\u6750\u8D28\u4E0E\u6C14\u8D28\u3002\u6B63\u6587\u914D\u56FE\u7684\u5185\u5BB9\u8868\u8FBE\u4F18\u5148\u4E8E\u5C01\u9762\u4E13\u7528\u7684\u201C\u5927\u6807\u9898+\u5355\u4E00\u96D5\u5851\u201D\u3001\u53EA\u5141\u8BB8\u6807\u9898\u6587\u5B57\u7B49\u7248\u5F0F\u9650\u5236\uFF0C\u53EF\u4F7F\u7528\u5C11\u91CF\u5185\u5BB9\u6807\u7B7E\u3001\u4EBA\u7269\u52A8\u4F5C\u4E0E\u5173\u7CFB\u7EBF\u3002\n\n\u901A\u8BFB\u8BE5\u7AE0\u5168\u90E8\u6B63\u6587\uFF0C\u63D0\u53D6\u6838\u5FC3\u5224\u65AD\u30012\u20144\u4E2A\u5173\u952E\u652F\u6491\u70B9\u548C\u5173\u7CFB\uFF08\u5206\u5DE5\u3001\u6D41\u7A0B\u3001\u56E0\u679C\u3001\u5BF9\u6BD4\u3001\u6761\u4EF6\uFF09\u3002\u628A\u5173\u7CFB\u53D8\u6210\u53EF\u89C1\u7684\u52A8\u4F5C\u3001\u573A\u666F\u3001\u7269\u4EF6\u4E0E\u5E03\u5C40\uFF0C\u63D0\u793A\u8BCD\u5199\u6E05\u5185\u5BB9\u4F9D\u636E\uFF0C\u4E0D\u80FD\u53EA\u8F93\u5165\u7AE0\u8282\u6807\u9898\u3002\u4E0D\u8981\u6C42\u9010\u53E5\u56FE\u89E3\uFF0C\u4E5F\u4E0D\u628A\u6574\u6BB5\u6587\u5B57\u585E\u8FDB\u56FE\u91CC\u3002\n\n\u56FE\u4E2D\u6587\u5B57\u4EE5\u7B80\u77ED\u89D2\u8272\u3001\u52A8\u4F5C\u6216\u5173\u7CFB\u6807\u7B7E\u4E3A\u4E3B\uFF0C\u7AE0\u8282\u6807\u9898\u53EF\u7701\u7565\u6216\u7F29\u5C0F\uFF0C\u4E0D\u80FD\u4E3B\u5BFC\u7248\u9762\u3002\u6CA1\u6709\u4F9D\u636E\u7684\u6570\u5B57\u3001\u4E8B\u5B9E\u4E0E\u80CC\u4E66\u4E0D\u5F97\u52A0\u5165\u3002\u7528\u6237\u8981\u65E0\u5B57\u56FE\u65F6\u7528\u753B\u9762\u8868\u8FBE\u5173\u7CFB\u3002\n\n\u6848\u4F8B\uFF1ATibo\u8BBF\u8C08\u9996\u7AE0\u5448\u73B0\u201C\u4EBA\u660E\u786E\u76EE\u6807\u3001\u7EC4\u7EC7\u4EFB\u52A1 \u2192 AI\u6267\u884C\u4EE3\u7801\u4E0E\u5206\u6790 \u2192 \u4EBA\u68C0\u9A8C\u7ED3\u679C\u3001\u5224\u65AD\u8D28\u91CF\u201D\uFF1B\u8D8B\u52BF\u5206\u6790\u3001\u4E1A\u52A1\u7406\u89E3\u3001\u529F\u80FD\u7814\u7A76\u3001\u53D1\u5E03\u590D\u76D8\u53EF\u4F5C\u4E3A\u6267\u884C\u7AEF\u5177\u4F53\u4EA7\u51FA\u3002\u4E0D\u80FD\u4EC5\u753B\u62BD\u8C61\u7684\u6548\u7387\u88C5\u7F6E\u548C\u5927\u6807\u9898\u3002\n\n\u6574\u7EC4\u6CBF\u7528\u540C\u4E00\u89C6\u89C9\u8BED\u8A00\uFF0C\u5404\u8282\u4E3B\u4F53\u548C\u5173\u7CFB\u987B\u6709\u533A\u522B\uFF0C\u907F\u514D\u91CD\u590D\u901A\u7528\u673A\u5668\u4EBA\u80CC\u666F\u3002\u6BCF\u5F20\u4FDD\u5B58\u72EC\u7ACB\u63D0\u793A\u8BCD\u3001\u56FE\u7247\u548C\u7AE0\u8282\u6620\u5C04\uFF0C\u4F7F\u7528article-slug-section-01\u7B49\u72EC\u7ACB\u8DEF\u5F84\uFF1B\u4FEE\u6539\u4FDD\u5B58\u7248\u672C\uFF0C\u4E0D\u8986\u76D6\u5DF2\u8BA4\u53EF\u56FE\u3002\n\n\u751F\u6210\u9636\u6BB5\u52A0\u8F7Dimagegen\u76F8\u5173Skill\u5E76\u8C03\u7528\u53EF\u7528\u56FE\u50CF\u5DE5\u5177\u3002\u65E0\u5DE5\u5177\u65F6\u4EA4\u4ED8\u63D0\u793A\u8BCD\u5E76\u8BF4\u660E\u672A\u751F\u6210\u3002\u53EA\u4F7F\u7528\u5DE5\u5177\u660E\u786E\u8FD4\u56DE\u7684\u56FE\u7247\u8DEF\u5F84\uFF0C\u4E0D\u626B\u63CF\u76EE\u5F55\u731C\u56FE\u3002\n\n## \u9996\u56FE\u8BD5\u770B\u4E0E\u786E\u8BA4\n\n\u9ED8\u8BA4\u56FA\u5B9A\u7B2C\u4E00\u6B63\u6587\u7AE0\u8282\uFF1B\u5F53\u6B21\u6307\u5B9A\u5176\u4ED6\u7AE0\u8282\u5219\u6309\u6307\u5B9A\u6267\u884C\u3002\u751F\u6210\u5E76\u5C55\u793A\u4E00\u5F20\u540E\u505C\u6B62\uFF0C\u7B49\u5F85\u7528\u6237\u786E\u8BA4\u3001\u4FEE\u6539\u3001\u9009\u62E9\u90E8\u5206\u7EE7\u7EED\u6216\u505C\u6B62\u3002\u4FEE\u6539\u53EA\u91CD\u505A\u9996\u56FE\uFF0C\u518D\u6B21\u5C55\u793A\uFF1B\u672A\u83B7\u786E\u8BA4\u4E0D\u5F00\u59CB\u5269\u4F59\u56FE\u3002\n\n\u5728\u9ED8\u8BA4\u5DE5\u4F5C\u6D41\u4E2D\uFF0C\u201C\u53EF\u4EE5/\u6EE1\u610F/\u6309\u8FD9\u4E2A\u7EE7\u7EED\u201D\u7B49\u660E\u786E\u63A5\u53D7\u9996\u56FE\u5373\u542F\u52A8\u5176\u4F59\u6B63\u6587\u5404\u7AE0\u8282\uFF1B\u5982\u679C\u7528\u6237\u9650\u5B9A\u8303\u56F4\uFF0C\u53EA\u5B8C\u6210\u8BE5\u8303\u56F4\u3002\u5DF2\u8BA4\u53EF\u9996\u56FE\u4E0D\u91CD\u505A\u3002\u4EC5\u8BA8\u8BBA\u6548\u679C\u3001\u4E0B\u8F7D\u6216\u6C89\u9ED8\u4E0D\u542F\u52A8\u540E\u7EED\u3002\n\n## \u5168\u90E8\u751F\u6210\n\n\u7528\u6237\u660E\u786E\u9009\u62E9\u5168\u90E8\u751F\u6210\u65F6\uFF0C\u98CE\u683C\u3001\u5C3A\u5BF8\u3001\u8303\u56F4\u5B8C\u6574\u540E\u5B8C\u6210\u5168\u90E8\u9009\u5B9A\u56FE\u7247\uFF0C\u4E0D\u8FFD\u52A0\u9010\u5F20\u786E\u8BA4\u3002\u9010\u5F20\u5DE5\u5177\u8C03\u7528\u4E5F\u6EE1\u8DB3\u8BE5\u6A21\u5F0F\u3002\u5931\u8D25\u4FDD\u7559\u5DF2\u5B8C\u6210\u7ED3\u679C\uFF0C\u91CD\u8BD5\u5931\u8D25\u9879\uFF1B\u6536\u5230\u4FEE\u6539\u540E\u8C03\u6574\u672A\u5B8C\u6210\u9879\u3002\n\n## \u6587\u4EF6\u4E0E\u6587\u7AE0\u56DE\u586B\n\n\u8BB0\u5F55\u7AE0\u8282\u3001\u63D0\u793A\u8BCD\u8DEF\u5F84\u3001\u5DE5\u5177\u56FE\u7247\u8DEF\u5F84\u3001\u72B6\u6001\u3001\u63D2\u5165\u4F4D\u7F6E\u3001\u98CE\u683C\u5C3A\u5BF8\u3002\u5C55\u793A\u9996\u56FE\u4E0E\u5B8C\u6210\u56FE\u7247\uFF0C\u63D0\u4F9B\u5B9E\u9645\u6587\u4EF6\u3002\n\n\u7528\u6237\u8981\u6C42\u52A0\u5165\u6587\u7AE0\u6216\u6709\u957F\u671F\u6388\u6743\u65F6\u624D\u56DE\u586B\uFF1BObsidian\u9644\u4EF6\u4E0E\u5D4C\u5165\u8DEF\u5F84\u987B\u771F\u5B9E\u6709\u6548\uFF0C\u5199\u5B8C\u6838\u5BF9\u94FE\u63A5\u5B58\u5728\u3002\u4FDD\u7559\u539F\u6709\u56FE\u7247\uFF0C\u66FF\u6362\u987B\u6388\u6743\u3002\u4E0D\u80FD\u51ED\u914D\u56FE\u8BF7\u6C42\u81EA\u52A8\u4E0A\u4F20\u3001\u53D1\u5E03\u6216\u5171\u4EAB\u3002\n";

