var __default2 = "# \u5199\u4F5C\u89C4\u5219\n\n\u9009\u4E2D\u4FEE\u6539\u3001\u5199\u5927\u7EB2\u3001\u5199\u6B63\u6587\u90FD\u4F1A\u5E26\u4E0A\u8FD9\u4EFD\u3002\u4F60\u53EF\u4EE5\u76F4\u63A5\u6539\u8FD9\u4E2A\u6587\u4EF6\uFF0C\u4E0B\u6B21\u8C03\u7528\u5C31\u751F\u6548\u3002\n\n- \u8BFB\u8005\u662F\u4E0D\u592A\u61C2\u6280\u672F\u7684\u4E2D\u6587\u666E\u901A\u4EBA\uFF0C\u5927\u767D\u8BDD\uFF0C\u4E0D\u7528\u672F\u8BED\uFF0C\u77ED\u53E5\u77ED\u6BB5\u3002\n- \u4E0D\u7528 用户 \u7684\u804C\u4E1A\u80CC\u666F\uFF08\u8D22\u52A1\u3001\u5BA1\u8BA1\u3001\u4F1A\u8BA1\u3001\u6295\u8D44\u5206\u6790\uFF09\u3002\n- \u4E0D\u7528\u300C\u300D\u300E\u300F\u8FD9\u7C7B\u5F15\u53F7\uFF0C\u4E0D\u7528\u7834\u6298\u53F7\uFF0C\u5C11\u7528\u5192\u53F7\u548C\u53CC\u5F15\u53F7\uFF0C\u8BFB\u8D77\u6765\u8981\u50CF\u771F\u4EBA\u968F\u624B\u5199\u7684\u3002\n- \u4E0D\u7F16\u6570\u5B57\u3001\u4E0D\u7F16\u7ECF\u5386\u3002\u9700\u8981\u4EB2\u624B\u505A\u6216\u4EB2\u8EAB\u7ECF\u5386\u7684\u5730\u65B9\uFF0C\u5199\u3010\u4F60\u6765\u8865\uFF1A\u63D0\u793A\u3011\u3002\n- \u4E0D\u7528\u8FD9\u4E9B\u8BCD\uFF1A\u9996\u5148\u5176\u6B21\u6700\u540E\u3001\u7EFC\u4E0A\u6240\u8FF0\u3001\u503C\u5F97\u6CE8\u610F\u7684\u662F\u3001\u8BF4\u767D\u4E86\u3001\u610F\u5473\u7740\u3001\u672C\u8D28\u4E0A\u3001\u6362\u53E5\u8BDD\u8BF4\u3001\u4E0D\u53EF\u5426\u8BA4\u3001\u5728\u5F53\u4ECAAI\u5FEB\u901F\u53D1\u5C55\u7684\u65F6\u4EE3\u3001\u8D4B\u80FD\u3001\u6293\u624B\u3001\u95ED\u73AF\u3002\n- \u5F00\u5934\u76F4\u63A5\u8BB2\u5177\u4F53\u7684\u4EBA\u548C\u4E8B\uFF0C\u60C5\u7EEA\u653E\u5728\u7ED3\u5C3E\u3002\n- \u6BCF\u7BC7\u90FD\u8981\u56DE\u7B54\u4E00\u4E2A\u95EE\u9898\uFF1A\u8BFB\u8005\u770B\u5B8C\u80FD\u62FF\u8D70\u4EC0\u4E48\u3002\n- \u4E0D\u5199\u5185\u6D4B\u3001\u5382\u5546\u5408\u4F5C\u3001\u8D44\u672C\u3001\u8BC9\u8BBC\u3001\u4EBA\u4E8B\u516B\u5366\u3002\n- \u5982\u679C\u548C\u5176\u4ED6\u5199\u4F5C\u65B9\u6CD5\uFF08\u6BD4\u5982 khazix-writer\uFF09\u51B2\u7A81\uFF0C\u4EE5\u8FD9\u4EFD\u4E3A\u51C6\u3002\n";

