    const skill = await this.skillText(this.settings.draftSkill, 2e4);
    let prepCtx = this.prepContext(await this.app.vault.read(file));
    try { const sk = await this.readText(this.p("规则", "公众号文章骨架库.md")); if (sk && prepCtx) prepCtx += "\n\n【公众号文章骨架库（从头部公众号高分文章提炼）】\n" + sk.slice(0, 8e3) + "\n\n从骨架库里挑最适合这个选题和角度的一种骨架来排大纲，在要点卡里写明用的是哪种骨架。"; } catch (e) {}
