    const modal = new ProcessModal(this, articleSlice(md).body.trim());
    modal.st.proc.format = "thread";
    modal.st.proc.noAutoImage = true;
    modal.st.proc.sourceArticlePath = file.path;
    modal.st.proc.note = "把这篇文章改编成中文 X 串帖。保留原文事实，不把播客嘉宾或主持人的经历写成作者经历，不添加未经核实的数据。结尾不写「信息来源：…」这种来源行。";
