      fm.status=records.length?"已发布":"准备中";fm["状态"]=fm.status;fm["处理状态"]=records.length?"已发布":"创作中";fm["归档状态"]=records.length?"已归档":"未归档";if(records.length){fm["工作台分类"]=this.articleCategory(fm);fm["归档日期"]=records.map(r=>r["日期"]).sort().at(-1);}
      if(wechat)fm.published={...(fm.published||{}),date:wechat["日期"],url:wechat["链接"]};
