      const newRecord = channel.value === "不新增发布记录" ? null : {渠道:channel.value,日期:date.value,链接:url.value.trim(),确认版本:2,用户确认已发布:true};
      if(newRecord && !publishedRecordChannel(newRecord))return new import_obsidian9.Notice("请填写有效的发布日期和已发布原文链接。公众号需 mp.weixin.qq.com 原文；X Article 需长文或发布分享链接，草稿链接不能入库。");
      save.disabled = true;
