    const matLink = "[[" + matPath.replace(/\.md$/, "") + "|\u7D20\u6750]]";
    const fm = ["---", "\u9009\u9898\u65E5\u671F: " + date, "\u7C7B\u578B: \u64AD\u5BA2\u8F6C\u6587\u7AE0", "\u5199\u6CD5: keke-podcast-to-article", "\u72B6\u6001: \u5199\u4F5C\u4E2D", "\u914D\u56FE\u8FDB\u5EA6: \u672A\u5F00\u59CB", "\u9009\u9898: " + JSON.stringify(title0), "\u7D20\u6750: " + JSON.stringify(matLink), mat.link ? "\u94FE\u63A5:\n  - " + mat.link : "", "---"].filter(Boolean).join("\n");
    const info = ["> [!info]- \u7D20\u6750\u60C5\u51B5", ...mat.notes.map((n) => "> - " + n), mat.transcript ? "> - \u6709\u6574\u671F\u6587\u5B57\u7A3F\uFF0C\u6309 keke \u7684\u5199\u6CD5\u53EF\u4EE5\u7528\u76F4\u63A5\u5F15\u7528" : "> - \u6CA1\u6709\u6574\u671F\u6587\u5B57\u7A3F\uFF0C\u53EA\u80FD\u5199\u8986\u76D6\u4E0D\u5B8C\u6574\u7684\u6574\u7406\u7A3F", "> - \u5B8C\u6574\u7D20\u6750\uFF1A" + matLink].join("\n");
    const notePath = this.p("\u7A3F\u4EF6", `${date} ${safe}.md`);
    const body = `${fm}
# ${title0}

${info}

%% \u5927\u7EB2\u5F00\u59CB %%
\uFF08\u8FD9\u7BC7\u6309 keke-podcast-to-article \u76F4\u63A5\u6210\u6587\uFF0C\u5199\u5B8C\u8FD9\u91CC\u4F1A\u5217\u51FA\u6587\u7AE0\u7ED3\u6784\u548C\u7F16\u8F91\u5907\u6CE8\uFF09
%% \u5927\u7EB2\u7ED3\u675F %%

## \u6B63\u6587

%% \u6B63\u6587\u5F00\u59CB %%
\uFF08\u6B63\u5728\u6309 keke \u7684\u5199\u6CD5\u5199\u6587\u7AE0\u2026\uFF09
%% \u6B63\u6587\u7ED3\u675F %%
`;
    let file = this.app.vault.getAbstractFileByPath(notePath);
    if (!(file instanceof import_obsidian14.TFile)) {
      await this.writeText(notePath, body);
      file = this.app.vault.getAbstractFileByPath(notePath);
    }
